  H('tlacaelel', '틀라카엘렐', 'm', [1480, 1487], 'mexico', 200, [56, 88, 60, 70], 'ops3 hist2', '11:3', '세 황제를 섬긴 아즈텍의 시우아코아틀. 늙었지만 눈빛은 날카롭다.', '아즈텍 제국의 실력자. 시우아코아틀(부왕)으로 여러 황제를 보필하며 제국의 제도와 신앙을 다듬었다. 1487년 무렵 세상을 떠났다.');
  H('nezahualpilli', '네사우알필리', 'm', [1480, 1515], 'mexico', 200, [54, 88, 50, 80], 'sci2 hist2 speech2', '11:3', '텍스코코의 시인 왕. 별을 보고 앞날을 점친다.', '텍스코코의 왕. 아버지 네사우알코요틀을 이어 시와 학문을 사랑했고, 별자리로 아즈텍 제국의 몰락을 예언했다고 전한다. 1515년 세상을 떠났다.');
  H('caonabo', '카오나보', 'm', [1480, 1496], 'antilles', 194, [78, 60, 84, 66], 'sword3 ops2', '11:3', '아이티섬 마과나의 카시케. 이방인들의 요새를 불태웠다.', '에스파뇰라섬 타이노족의 추장. 콜론이 남긴 라 나비다드 요새를 없앴고, 1495년 붙잡혀 에스파냐로 실려 가던 중 바다에서 세상을 떠났다.');
  H('guarionex', '과리오넥스', 'm', [1480, 1502], 'antilles', 194, [66, 66, 64, 70], 'ops2 speech1', '11:3', '마구아의 카시케. 평화를 원하지만 공물 요구에 지쳐 간다.', '에스파뇰라섬 타이노족의 추장. 에스파냐인의 공물 요구에 맞서다 붙잡혀, 1502년 에스파냐로 실려 가던 배가 폭풍에 가라앉아 세상을 떠났다.');
  H('anacaona', '아나카오나', 'f', [1490, 1503], 'antilles', 194, [44, 80, 30, 92], 'music3 speech2', '11:3', '하라과의 여성 카시케. 노래 「아레이토」를 짓는 시인이다.', '에스파뇰라섬 하라과의 여성 추장이자 시인. 카오나보의 아내로 에스파냐인을 맞아들였으나, 1503년 총독 오반도의 손에 목숨을 잃었다.');
  H('hatuey', '아투에이', 'm', [1495, 1512], 'antilles', 195, [72, 64, 74, 70], 'sword2 ops2 theo1', '11:3', '바다를 건너 쿠바로 온 카시케. 이방인들이 섬기는 신은 황금이라고 말한다.', '에스파뇰라섬에서 쿠바로 건너간 타이노족 추장. 에스파냐의 정복에 맞서 싸우다 1512년 붙잡혀 화형을 당했다.');
  H('xicotencatl', '시코텐카틀', 'm', [1505, 1521], 'mexico', 202, [76, 62, 84, 64], 'sword3 ops2', '11:3', '틀락스칼라의 젊은 전사. 낯선 손님들을 믿지 말자고 말한다.', '틀락스칼라의 장수. 코르테스와의 동맹에 반대했으나 받아들여지지 않았고, 1521년 에스파냐인 손에 처형되었다.');
  H('guerrero', '곤살로 게레로', 'm', [1511, 1536], 'mexico', 206, [72, 66, 78, 70], 'sword3 ops2', '11:3 0:2', '유카탄에 표류해 마야의 전사가 된 이방인. 얼굴에 문신을 했다.', '에스파냐의 선원. 1511년 유카탄 해안에 표류해 마야 사회에 들어가 추장의 딸과 결혼하고 장수가 되었다. 동료 아길라르와 달리 돌아가지 않았고, 1536년 에스파냐군과 싸우다 전사했다고 전한다.', { pool: 'es', style: 'az' });
  H('cuauhtemoc', '쿠아우테목', 'm', [1515, 1525], 'mexico', 200, [74, 70, 86, 76], 'ops2 sword3', '11:3', '테노치티틀란의 젊은 장수. 「내려앉는 독수리」라는 이름을 가졌다.', '아즈텍 제국의 마지막 황제. 1521년 테노치티틀란이 함락될 때까지 싸웠고, 1525년 코르테스의 원정에 끌려갔다가 처형되었다.');
  H('enriquillo', '엔리키요', 'm', [1515, 1535], 'antilles', 194, [70, 70, 76, 74], 'sword3 ops2', '11:3 0:2', '수도원에서 글을 배운 카시케. 산으로 들어가 싸운다.', '에스파뇰라섬 타이노족의 추장. 수도사들에게 교육을 받았으나 학대에 맞서 1519년 산으로 들어가 14년을 싸웠고, 1533년 에스파냐 왕과 평화 협정을 맺었다.');
  H('ruminahui', '루미냐위', 'm', [1500, 1535], 'andes', 219, [76, 70, 82, 64], 'ops3 sword2', '11:3', '키토를 지키는 잉카의 장수. 「돌의 눈」이라 불린다.', '잉카 제국의 장수. 아타우알파가 처형된 뒤 키토에서 에스파냐군에 맞섰고, 잉카의 황금을 숨겼다는 전설이 있다. 1535년 처형되었다.');
  H('quizquiz', '키스키스', 'm', [1500, 1535], 'andes', 223, [72, 66, 80, 60], 'ops3 sword2', '11:3', '아타우알파 편의 노장. 쿠스코를 차지했던 장수다.', '잉카 제국의 장수. 내전에서 아타우알파 편에 서서 쿠스코를 차지했고, 에스파냐군과 싸우다 1535년 부하들 손에 목숨을 잃었다.');
  H('chalcuchimac', '찰쿠치마', 'm', [1500, 1533], 'andes', 223, [74, 64, 82, 58], 'sword3 ops2', '11:3', '잉카 북부군의 장수. 군대가 지나는 길마다 창고가 열린다.', '잉카 제국의 장수. 아타우알파 편의 명장으로 와스카르를 사로잡았으나, 1533년 에스파냐인에게 화형을 당했다.');
  H('caramuru', '카라무루', 'm', [1510, 1557], 'brazil', 215, [66, 66, 60, 76], 'speech3 nav2', '1:3 11:3', '바이아 해안에 난파해 투피남바족 사이에서 사는 포르투갈 사내.', '포르투갈의 선원 디오구 알바레스 코헤이아. 1510년 무렵 바이아 해안에 난파해 투피남바족과 살며 「카라무루」라 불렸고, 포르투갈인과 원주민 사이를 이었다.', { pool: 'pt', style: 'co' });
  H('paraguacu', '파라과수', 'f', [1525, 1583], 'brazil', 215, [48, 70, 34, 86], 'speech2 nav1', '11:3 1:2', '투피남바 추장의 딸. 남편을 따라 프랑스까지 바다를 건넜다.', '투피남바족 여인. 카라무루와 결혼해 1528년 함께 프랑스에 건너가 세례를 받았다고 전한다. 바이아의 어머니로 기억된다.');
  H('nachicocom', '나치 코콤', 'm', [1530, 1562], 'mexico', 206, [64, 74, 66, 70], 'ops2 hist1', '11:3', '소투타의 마야 군주. 조상 대대로의 원한을 잊지 않는다.', '유카탄 소투타의 마야 군주. 오랫동안 에스파냐의 정복에 맞섰고, 원수 가문 시우 가문의 순례단을 죽인 일로 이름이 남았다.');
  H('cunhambebe', '쿠냠베베', 'm', [1540, 1555], 'brazil', 216, [82, 56, 84, 66], 'sword3 ops2', '11:3', '타모이오족의 큰 추장. 대포를 어깨에 메고 쏜다는 거인이다.', '브라질 타모이오족의 추장. 포르투갈에 맞선 타모이오 동맹을 이끌었고, 붙잡혔던 독일인 한스 슈타덴의 기록에 등장한다. 1555년 무렵 세상을 떠났다.');
  H('tibirica', '티비리사', 'm', [1530, 1562], 'brazil', 278, [66, 66, 64, 70], 'ops2 speech1', '11:3', '피라치닝가의 투피 추장. 예수회 신부들에게 마을을 열어 주었다.', '투피니킹족의 추장. 예수회와 손잡아 상파울루가 세워지도록 도왔고, 1562년 다른 부족의 공격을 막다 세상을 떠났다.');
  H('titucusi', '티투 쿠시 유팡키', 'm', [1550, 1571], 'andes', 223, [60, 78, 60, 74], 'hist2 ops2', '11:3', '빌카밤바 산속에 남은 잉카의 왕. 이야기를 받아 적게 한다.', '빌카밤바에 남은 잉카 왕국의 군주. 에스파냐와 협상하며 버텼고, 정복의 역사를 구술해 기록으로 남겼다. 1571년 세상을 떠났다.');
  H('arariboia', '아라리보이아', 'm', [1555, 1589], 'brazil', 216, [74, 62, 78, 66], 'sword2 ops2', '11:3', '테미미노족의 추장. 과나바라만의 섬을 내주지 않으려 싸운다.', '테미미노족의 추장. 포르투갈 편에 서서 1567년 과나바라만에서 프랑스인을 몰아내는 데 공을 세웠고, 그 대가로 땅을 받아 니테로이를 세웠다.');
  H('chi', '가스파르 안토니오 치', 'm', [1555, 1610], 'mexico', 206, [48, 82, 30, 74], 'speech3 hist2', '11:3 0:2', '마야 귀족 집안 출신 통역. 두 세계의 말을 모두 적는다.', '마야 귀족 출신의 통역이자 학자. 에스파냐 수도사들과 일하며 유카탄의 역사와 풍습을 기록했다.');
  H('guamanpoma', '와만 포마 데 아얄라', 'm', [1560, 1616], 'andes', 223, [52, 82, 30, 66], 'hist3 art2', '11:3 0:2', '천 장이 넘는 그림 편지를 쓰는 안데스의 노인.', '페루의 원주민 귀족. 그림 400여 장을 곁들인 1200쪽짜리 편지 『새 연대기와 좋은 정치』를 써서 식민 지배의 부당함을 에스파냐 왕에게 알리려 했다.');
  H('garcilaso', '잉카 가르실라소 데 라 베가', 'm', [1555, 1616], 'andes,iberia', 223, [52, 86, 50, 74], 'hist3 speech1', '11:3 0:3', '잉카 공주와 에스파냐 장교 사이에서 난 사람. 어머니의 나라 이야기를 쓴다.', '에스파냐 장교와 잉카 공주 사이에서 태어난 역사가. 1560년 에스파냐로 건너가 잉카의 역사와 풍습을 담은 『잉카 왕실 해설』을 썼다. 1616년 세상을 떠났다.', { pool: 'inca', style: 'an' });
  H('powhatan', '포와탄', 'm', [1580, 1618], 'firstnations', 236, [66, 80, 66, 76], 'ops3 speech1', '15:3', '서른 부족을 거느린 대추장. 바다에서 온 이방인을 지켜본다.', '체서피크만 일대 30여 부족 연합의 대추장 와훈세나카우. 제임스타운의 영국인들과 다투고 화해하기를 거듭했다. 1618년 세상을 떠났다.');
  H('opechancanough', '오페찬카누', 'm', [1590, 1646], 'firstnations', 236, [70, 76, 74, 66], 'ops3 sword2', '15:3', '포와탄의 동생. 이방인들을 몰아내려 오래 준비한다.', '포와탄의 동생. 형의 뒤를 이어 1622년과 1644년 두 번 영국 정착촌을 공격했다. 1646년 붙잡혀 목숨을 잃었다.');
  H('squanto', '스콴토', 'm', [1605, 1622], 'firstnations', 237, [60, 72, 40, 80], 'speech3 nav1', '15:3 3:2 0:1', '대서양 건너편에 끌려갔다 돌아온 파툭셋 사람. 이방인의 말을 한다.', '파툭셋족 사람 티스콴텀. 1614년 붙잡혀 에스파냐로 팔려 갔다가 잉글랜드를 거쳐 돌아왔으나 마을은 역병으로 사라져 있었다. 플리머스 정착민들에게 옥수수 농사를 가르쳤다.');
  H('pocahontas', '포카혼타스', 'f', [1608, 1617], 'firstnations', 236, [52, 72, 36, 90], 'speech2', '15:3 3:1', '포와탄의 장난꾸러기 딸. 이방인 마을을 거리낌 없이 드나든다.', '포와탄의 딸 마토아카. 영국인에게 붙잡혔다가 존 롤프와 결혼해 1616년 런던에 건너갔고, 돌아오는 길에 1617년 세상을 떠났다.');
  H('massasoit', '마사소이트', 'm', [1610, 1661], 'firstnations', 237, [64, 74, 60, 78], 'ops2 speech2', '15:3', '왐파노아그의 대추장. 이방인과 평화를 맺기로 마음먹었다.', '왐파노아그족의 대추장 우사메퀸. 1621년 플리머스 정착민과 동맹을 맺어 오래 평화를 지켰다. 1661년 세상을 떠났다.');
